import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.CrXGS008.js";const b=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"repair-station-business/settings.md","filePath":"repair-station-business/settings.md"}'),r={name:"repair-station-business/settings.md"};function n(s,t,i,c,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Every Repair Station Business setting is edited in <code>/nay</code>, on the <strong>Repair Station Business</strong> page (scope <code>nay_repair_business.config</code>). Changes are saved in the database and applied to every player at once. <code>config.lua</code> holds optional starting values: they apply until a setting is changed in <code>/nay</code>, and <strong>Reset</strong> goes back to them.</p><p>The <strong>In /nay</strong> column is the name shown in the panel. The key is the name used by <code>config.lua</code> and the <a href="/nay-lib/api">HTTP API</a>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Enabled</td><td><code>Enabled</code></td><td>on / off</td><td>on</td><td>Turns the business features on or off. Off, stations behave like plain Repair Stations.</td></tr><tr><td>Stations for sale without owner</td><td><code>UnownedMode</code></td><td><code>open</code> or <code>closed</code></td><td><code>open</code></td><td>Open: players can still repair there. Closed: the station refuses repairs until someone buys it.</td></tr></tbody></table><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Stations for sale</td><td><code>Purchasable</code></td><td>list, up to 64</td><td>none</td><td>Stations players can buy. Use the admin panel to manage them in game.</td></tr><tr><td>Stations per player</td><td><code>MaxStationsPerPlayer</code></td><td>number, 1 to 16</td><td>1</td><td>How many stations one player can own.</td></tr><tr><td>Purchase account</td><td><code>BuyAccount</code></td><td><code>cash</code> or <code>bank</code></td><td><code>bank</code></td><td>Account the purchase price is taken from.</td></tr><tr><td>Sell back (%)</td><td><code>SellBackPercent</code></td><td>number, 0 to 100</td><td>50</td><td>Share of the purchase price paid back when the owner sells or loses the station.</td></tr><tr><td>Inactivity limit (days)</td><td><code>InactivityDays</code></td><td>number, 0 to 90</td><td>14</td><td>An owner who does not open the tablet for this long loses the station and is paid back. 0 disables it.</td></tr></tbody></table><h2 id="stock" tabindex="-1">Stock <a class="header-anchor" href="#stock" aria-label="Permalink to &quot;Stock&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Stock capacity</td><td><code>Capacity</code></td><td>number, 10 to 10000</td><td>100</td><td>Maximum number of parts a station can hold.</td></tr><tr><td>Parts for the engine</td><td><code>PartsEngine</code></td><td>number, 0 to 100</td><td>2</td><td>Parts used by a service that repairs the engine.</td></tr><tr><td>Parts for the body</td><td><code>PartsBody</code></td><td>number, 0 to 100</td><td>3</td><td>Parts used by a service that repairs the body.</td></tr><tr><td>Parts for the tyres</td><td><code>PartsTyres</code></td><td>number, 0 to 100</td><td>1</td><td>Parts used by a service that repairs the tyres.</td></tr><tr><td>Restock mode</td><td><code>RestockMode</code></td><td><code>purchase</code>, <code>items</code> or <code>both</code></td><td><code>both</code></td><td>How owners fill the stock.</td></tr><tr><td>Price per part</td><td><code>PartPrice</code></td><td>number, 0 to 100000</td><td>40</td><td>Paid from the owner&#39;s bank when buying parts.</td></tr><tr><td>Parts item</td><td><code>PartItem</code></td><td>text, 1 to 64 characters</td><td><code>repair_parts</code></td><td>Inventory item handed in to restock.</td></tr><tr><td>Parts per item</td><td><code>PartsPerItem</code></td><td>number, 1 to 100</td><td>5</td><td>Parts added to the stock by one item.</td></tr><tr><td>Low stock alert</td><td><code>LowStockThreshold</code></td><td>number, 0 to 10000</td><td>10</td><td>The owner is warned when the stock falls under this number. 0 disables it.</td></tr></tbody></table><h2 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Lowest price (%)</td><td><code>MinPricePercent</code></td><td>number, 10 to 100</td><td>50</td><td>Lowest share of the service price an owner can set.</td></tr><tr><td>Highest price (%)</td><td><code>MaxPricePercent</code></td><td>number, 100 to 500</td><td>200</td><td>Highest share of the service price an owner can set.</td></tr><tr><td>Tax (%)</td><td><code>TaxPercent</code></td><td>number, 0 to 90</td><td>10</td><td>Share of every repair payment that does not reach the till.</td></tr></tbody></table><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Owned station blip color</td><td><code>OwnedBlipColor</code></td><td>number, 0 to 85</td><td>2</td><td>Blip color of the stations you own, on your map.</td></tr><tr><td>Station for sale blip color</td><td><code>ForSaleBlipColor</code></td><td>number, 0 to 85</td><td>5</td><td>Blip color of the stations for sale.</td></tr></tbody></table><p>Entries of <strong>Stations for sale</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th></tr></thead><tbody><tr><td>Station identifier</td><td><code>StationId</code></td><td>8 characters (0 to 9, a to f), as in the Repair Station editor.</td></tr><tr><td>Price</td><td><code>Price</code></td><td>number, 0 to 100000000</td></tr></tbody></table><p>The percentages of the owner (<code>MinPricePercent</code>, <code>MaxPricePercent</code>) apply to the price of each service, before job discounts. The tax (<code>TaxPercent</code>) is taken from each repair payment before it reaches the till.</p>',16)])])}const u=e(r,[["render",n]]);export{b as __pageData,u as default};
